import{_ as a,C as o,o as r,c as d,E as i,a2 as n}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"证据包：批准对象与动作身份","description":"","frontmatter":{"title":"证据包：批准对象与动作身份","outline":"deep"},"headers":[],"relativePath":"zh/research/evidence/2026-09-04-approval-operation-identity.md","filePath":"zh/research/evidence/2026-09-04-approval-operation-identity.md","lastUpdated":1788532182000}'),l={name:"zh/research/evidence/2026-09-04-approval-operation-identity.md"};function s(c,e,p,h,_,f){const t=o("ArticleTableScroll");return r(),d("div",null,[i(t,{language:"zh"}),e[0]||(e[0]=n('<h1 id="配套证据-批准对象与动作身份" tabindex="-1">配套证据：批准对象与动作身份 <a class="header-anchor" href="#配套证据-批准对象与动作身份" aria-label="Permalink to &quot;配套证据：批准对象与动作身份&quot;">​</a></h1><p>本包配合<a href="/joinwell52/zh/engineering/2026-09-04-approval-operation-identity">中文正文</a>使用。<a href="/joinwell52/en/research/evidence/2026-09-04-approval-operation-identity">English guide</a>。性质：<strong>公开配套的受控实验记录；不是修复回执或独立 QA。</strong></p><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><p>本包提供原研究记录的去标识摘取，不是假装重新运行的结果。所有观察固定在 CodeFlowMu 提交 <code>fdadbed489129455437f25202a03bae6e0c2e822</code>，实验日期为 2026-09-04。</p><table tabindex="0"><thead><tr><th>正文主张</th><th>记录位置</th><th>校验及预期</th><th>支持范围</th></tr></thead><tbody><tr><td>既有保护两轮通过</td><td><code>observations.json → baseline_tests</code></td><td>每轮 31 tests/pass，fail/skip=0，退出 0</td><td>选定四个测试文件，不是全产品验收</td></tr><tr><td>同会话改分支消费旧批准</td><td><code>approval_matrix</code> 中 <code>different-target</code></td><td>两轮 ALLOW，consumed，重复为 APPROVAL_ALREADY_CONSUMED</td><td>真实 Native gate；无命令执行</td></tr><tr><td>换成登记的唤醒 Session 失配</td><td><code>approval_matrix</code> 中 <code>delivered-resume</code></td><td>两轮 REQUIRE_APPROVAL，原授权 available</td><td>受控会话输入，不证明完整 successor 准入</td></tr><tr><td>四种 Git 变化摘要一致</td><td><code>field_comparisons</code> 中 branch/remote/force/delete</td><td>每种两轮 fingerprint/digest 相同，request_differences 空</td><td>摘要边界，不代表四种操作均消费/执行</td></tr><tr><td>嵌套 Session 造成摘要变化</td><td><code>field_comparisons</code> 中 new-session</td><td>fingerprint 相同、digest 不同；仅排除嵌套 Session 的内存反事实使 digest 相同</td><td>定位原因，不是产品补丁</td></tr><tr><td>Codex resolution 接受改分支</td><td><code>codex_resolution</code> 中 changed-branch</td><td>两轮 allow=true、授权 consumed；same-command 是正对照</td><td>本地真实 resolution 函数，不是在线 app-server 测试</td></tr><tr><td>同文 TASK 不替代指定依赖</td><td><code>lineage_controls</code></td><td>六种情况每种两轮，actual 符合 expected</td><td>FCoP gate 分支，不是全部关系图恢复</td></tr></tbody></table><h2 id="来源和核验方式" tabindex="-1">来源和核验方式 <a class="header-anchor" href="#来源和核验方式" aria-label="Permalink to &quot;来源和核验方式&quot;">​</a></h2><ul><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/approval-identity-20260904/evidence/observations.json" target="_blank" rel="noreferrer">观察数据</a>：逐轮结果及四个保留的断言失败。</li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/approval-identity-20260904/evidence/sources.json" target="_blank" rel="noreferrer">来源定位</a>：Codex PR 元数据，以及固定 CodeFlowMu 文件的 SHA-256。</li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/approval-identity-20260904/evidence/manifest.json" target="_blank" rel="noreferrer">完整性清单</a>：正文、双语说明和数据的文件摘要。</li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/approval-identity-20260904/evidence/check-evidence.mjs" target="_blank" rel="noreferrer">读取校验器</a>：运行 <code>node check-evidence.mjs</code>。</li></ul><p>校验器依次检查文件完整性、实验集合、正反对照及文章所引用的比较。预期输出为 <code>RECORDED EVIDENCE CONSISTENT; PRODUCT COUNTEREXAMPLES REMAIN</code>。这表示记录与主张一致，<strong>不是产品通过</strong>。</p><p>原研究的完整 E1 探针因两类偏离各出现两次而退出 1；本包不会将它洗成通过。因果采集脚本的退出 0 也仅表示采集完成。31 项回归、22 次审批输入、14 次字段比较、4 次 resolution、12 次 lineage 观察是不同集合，不应相加为可靠率。</p><h2 id="去标识规则" tabindex="-1">去标识规则 <a class="header-anchor" href="#去标识规则" aria-label="Permalink to &quot;去标识规则&quot;">​</a></h2><p>全部项目、任务和命令原本就是隔离合成夹具，没有客户事故记录。导出进一步将本机夹具路径替换为稳定的 <code>&lt;SYNTHETIC_FIXTURE_...&gt;</code> 标签，省略进程号码；保留顺序、轮次、时间、输入语义、输出、失败与原始摘要。标签不是可执行路径。</p><p><strong>保留的 operation digest 是原始观察值，不能用去路径后的 JSON 重新计算来验证它。</strong> 校验器检查记录之间的等式/不等式及原始文件摘要引用；完整产品复跑需要原研究脚本、固定源码及相应依赖。本包的 reader 不是产品实验 runner，不依靠它证明因果或真实网络执行。</p><p>没有删除失败事实，也没有把 force/delete 摘要等价扩大为真实 Git 操作结果。原始研究中的工具使用错误、spec/TAP 计数修订及不完整调试轮不进入计数；相关限制在<a href="/joinwell52/zh/engineering/2026-09-04-approval-operation-identity">正文第 6 节</a>及原研究记录中保留。本包只覆盖正文引用的完成轮次。</p><p>尚未执行真实推送、云模型、线上接管、掉电恢复或独立 QA。全文及证据说明中英文采用同一份机器可读数据。</p><h2 id="下载后离线检查" tabindex="-1">下载后离线检查 <a class="header-anchor" href="#下载后离线检查" aria-label="Permalink to &quot;下载后离线检查&quot;">​</a></h2><p><a href="https://joinwell52-ai.github.io/joinwell52/assets/approval-identity-20260904/approval-identity-evidence.zip" target="_blank" rel="noreferrer">下载完整配套包（ZIP）</a>，解压后进入 evidence 目录运行 <code>node check-evidence.mjs</code>。请保留完整目录结构；单独下载脚本不足以完成文件完整性检查。</p>',16))])}const v=a(l,[["render",s]]);export{g as __pageData,v as default};
